import{_ as r,o as a,c as t,a3 as o}from"./chunks/framework.DjfA6S92.js";const u=JSON.parse('{"title":"Introduce","description":"","frontmatter":{"title":"Introduce"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),n={name:"guide/index.md"};function i(c,e,d,s,p,h){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="introduce" tabindex="-1">Introduce <a class="header-anchor" href="#introduce" aria-label="Permalink to &quot;Introduce&quot;">​</a></h1><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>网络上的资源其实已经足够多了，所以在进行搜索的时候需要极大的筛选成本。为了减少这种低效的筛选，我将一些零散的知识整理在一起。</p><h2 id="guidance" tabindex="-1">Guidance <a class="header-anchor" href="#guidance" aria-label="Permalink to &quot;Guidance&quot;">​</a></h2><p><code>Entry</code>这个部分是几个前端知识库的链接，里面的内容比较浅显易懂。先看看整个结构性的题目，找到自己的知识的盲区，再去针对性学习。</p><p><code>Basic</code>是一些基础、简单的面试题，可以在<code>Entry</code>中的找到更全的题目内容。</p><p><code>Advanced</code>则是一些稍微有难度的题目，主要来自于日常的思考、交流，以及一些常见的前端的进阶问题、算法题。</p><p><code>Framework</code>则是跟框架、原理相关的题目。</p><p><code>Team</code>这个部分则是关于团队管理、以及个人非技术上的一些发展相关的杂谈。</p><p><code>Foundation</code>这个部分是计算机基础的概念，包括计算机组成原理、操作系统、编译原理、计算机网络、数据结构与算法、数据库系统、软件工程。这个部分就是所谓的补基础，构建完整的计算机体系结构，是向上成长的过程中必不可少的。</p><h3 id="进阶-interview-compass" tabindex="-1">进阶：Interview Compass <a class="header-anchor" href="#进阶-interview-compass" aria-label="Permalink to &quot;进阶：Interview Compass&quot;">​</a></h3><p>完成知识梳理后，可以继续使用 <a href="https://liyuk.github.io/interview-compass/" target="_blank" rel="noreferrer">Interview Compass</a> 练习如何表达自己的经历。这套问题框架覆盖从初级工程师、资深工程师到资深技术管理者的不同职责阶段，通过问题意图、上下文追问和可观察的信号，帮助候选人准备面试表达，也为面试官设计问题、工程师进行晋升复盘提供参考。选择与你目标和职责阶段相符的问题，结合自己的具体经历说明背景、行动、判断与结果；这些信号用于辅助思考，不是标准答案或机械评分表。</p><p><strong>对于这种资讯类的repo来说，很少有提及基础的重要性，希望能够引起阅读者的重视</strong>。</p><p><strong>欢迎大家在issue里留下自己的奇思妙想，或者直接pr。</strong></p><h2 id="hortation" tabindex="-1">Hortation <a class="header-anchor" href="#hortation" aria-label="Permalink to &quot;Hortation&quot;">​</a></h2><p>希望大家能够带着成为一个优秀的软件工程师的想法，来合理的利用这份资料。</p><p>这份资料并非单纯的前端工程师的面试题，我更希望它能够在工程师成长的道路上，起到梳理知识结构的作用。可以精通前端，但不要局限在狭义的前端，将知识面扩展到后端，了解更多基础的知识结构，才能够成为更加优秀的工程师。</p><p>这里面大部分的题目都是非常规的提问法，但涉及知识点都极其基础。后续我们可能会添加一些别的方向的内容，比如node、go之类的，但主要还是跟进前端的新动态。</p><p>最后提到需要辩证地看待这种资源，它只是知识结构，而非万灵药，更多的知识还需要在工作中去实践、去学习。</p><p><strong>“非知之难，行之惟难；非行之难，终之斯难。”——魏征</strong></p><h2 id="contributors" tabindex="-1">Contributors <a class="header-anchor" href="#contributors" aria-label="Permalink to &quot;Contributors&quot;">​</a></h2><p><a href="https://github.com/Liyuk" target="_blank" rel="noreferrer">@liyuk</a><br><a href="https://github.com/dcy0701" target="_blank" rel="noreferrer">@onion</a><br><a href="https://github.com/NE-SmallTown" target="_blank" rel="noreferrer">@heaven</a><br><a href="https://github.com/Troland" target="_blank" rel="noreferrer">@Tristan</a><br><a href="https://github.com/q986171791" target="_blank" rel="noreferrer">@张庆东</a><br><a href="https://github.com/moyuling" target="_blank" rel="noreferrer">@moyu</a></p>',22)])])}const b=r(n,[["render",i]]);export{u as __pageData,b as default};
